    "tapOriginal": "ਅਸਲੀ ਦਿਖਾਉਣ ਲਈ ਟੈਪ ਕਰੋ",
    "tapTranslation": "ਅਨੁਵਾਦ ਦਿਖਾਉਣ ਲਈ ਟੈਪ ਕਰੋ",
    "scanLabel": "Cooling system",
    "sourceLanguage": "ਸਰੋਤ ਭਾਸ਼ਾ",
    "targetLanguage": "ਟੀਚਾ ਭਾਸ਼ਾ",
    "swapLanguages": "ਭਾਸ਼ਾਵਾਂ ਬਦਲੋ",
    "modelMemoryWarning": "ਇਸ ਮਾਡਲ ਲਈ ਉਪਲਬਧ ਮੈਮੋਰੀ ਤੋਂ ਵੱਧ ਮੈਮੋਰੀ ਲੱਗ ਸਕਦੀ ਹੈ। ਤੁਸੀਂ ਕੋਸ਼ਿਸ਼ ਕਰ ਸਕਦੇ ਹੋ; ਮੈਮੋਰੀ ਘੱਟ ਹੋਣ ਤੇ ਪ੍ਰਗਤੀ ਸੰਭਾਲ ਕੇ ਅਨੁਵਾਦ ਰੁਕ ਜਾਵੇਗਾ।",
    "modelPairUnrated": "ਇਸ ਭਾਸ਼ਾ ਜੋੜੇ ਦੀ ਗੁਣਵੱਤਾ ਦਾ ਮੁਲਾਂਕਣ ਨਹੀਂ ਕੀਤਾ ਗਿਆ।",
    "modelEvidenceLine": "{total} ਜਾਂਚ ਅੰਸ਼ਾਂ ਵਿੱਚੋਂ {acceptable} ਵਿੱਚ ਅਰਥ ਕਾਇਮ ਰਿਹਾ",
    "modelEvidenceCaveat": "ਸਬੂਤ ਵਿੱਚ ਸਿਰਫ਼ ਅੰਗਰੇਜ਼ੀ ਤੋਂ ਰੂਸੀ ਦੇ 44 ਤਕਨੀਕੀ ਹਿੱਸੇ ਹਨ। ਇਹ ਹੋਰ ਜੋੜਿਆਂ ਜਾਂ ਦਸਤਾਵੇਜ਼ਾਂ ਦੀ ਗੁਣਵੱਤਾ ਨਹੀਂ ਦੱਸਦਾ।",
    "modelChoiceBody": "ਨਮੂਨੇ ਦੇ ਨਤੀਜੇ ਅਤੇ ਡਾਊਨਲੋਡ ਆਕਾਰ ਮੁਤਾਬਕ ਚੁਣੋ।",
    "modelTierCompact": "ਕੰਪੈਕਟ ਪੱਧਰ",
    "modelTierBalanced": "ਸੰਤੁਲਿਤ ਪੱਧਰ",
    "modelTierQuality": "ਗੁਣਵੱਤਾ ਪੱਧਰ",
    "modelTierTradeoffCompact": "ਸਭ ਤੋਂ ਛੋਟਾ ਡਾਊਨਲੋਡ; ਅੰਗਰੇਜ਼ੀ-ਰੂਸੀ ਨਮੂਨੇ ਦਾ ਸਭ ਤੋਂ ਘੱਟ ਨਤੀਜਾ।",
    "modelTierTradeoffBalanced": "ਦਰਮਿਆਨਾ ਡਾਊਨਲੋਡ; ਸੁਰੱਖਿਅਤ ਸ਼ਬਦਾਵਲੀ ਲਾਗੂ ਨਹੀਂ ਹੁੰਦੀ।",
    "modelTierTradeoffQuality": "ਸਭ ਤੋਂ ਵੱਡਾ ਡਾਊਨਲੋਡ ਅਤੇ ਮੈਮੋਰੀ ਅੰਦਾਜ਼ਾ; ਅੰਗਰੇਜ਼ੀ-ਰੂਸੀ ਨਮੂਨੇ ਦਾ ਸਭ ਤੋਂ ਉੱਚਾ ਨਤੀਜਾ।",
    "modelMemoryEstimate": "ਪੂਰੀ ਪ੍ਰਕਿਰਿਆ ਲਈ ਮੈਮੋਰੀ ਅੰਦਾਜ਼ਾ (ਰਾਖਵੀਂ ਮੈਮੋਰੀ ਤੋਂ ਬਿਨਾਂ)",
    "modelResourceMemory": "ਇਸ ਮਾਡਲ ਅਤੇ ਪ੍ਰਕਿਰਿਆ ਲਈ ਉਪਲਬਧ ਮੈਮੋਰੀ ਕਾਫ਼ੀ ਨਹੀਂ ਹੈ।",
    "modelResourceDisk": "ਇਸ ਡਾਊਨਲੋਡ ਲਈ ਖਾਲੀ ਸਟੋਰੇਜ ਕਾਫ਼ੀ ਨਹੀਂ ਹੈ।",
    "modelResourceLowMemory": "ਸਿਸਟਮ ਘੱਟ ਮੈਮੋਰੀ ਦੱਸਦਾ ਹੈ। ਹੋਰ ਕੰਮ ਬੰਦ ਕਰਕੇ ਮੁੜ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
    "modelResourceUnsupported": "ਇਹ ਮਾਡਲ ਚਾਲੂ ਨਹੀਂ ਜਾਂ ਸਰੋਤ ਅੰਦਾਜ਼ਾ ਉਪਲਬਧ ਨਹੀਂ।",
