    "modelVerifyOriginal": "ਜਾਂਚੇ ਅੰਸ਼ਾਂ ਵਿੱਚ ਤਕਨੀਕੀ ਗਲਤੀਆਂ ਸਨ। ਚੇਤਾਵਨੀਆਂ, ਅੰਕ, ਪੁਰਜ਼ੇ ਅਤੇ ਕਦਮ ਮੂਲ ਨਾਲ ਮਿਲਾਓ।",
    "modelGlossaryUnsupported": "ਇਹ ਮਾਡਲ ਸੰਭਾਲੀ ਸ਼ਬਦਾਵਲੀ ਨਹੀਂ ਵਰਤ ਸਕਦਾ। ਸਮਰਥਿਤ ਮਾਡਲ ਚੁਣੋ ਜਾਂ ਅਨੁਵਾਦ ਤੋਂ ਪਹਿਲਾਂ ਸ਼ਬਦ ਹਟਾਓ।",
