    "intro3Body": "பதிவிறக்குவதற்கு முன் மாதிரி அளவு மற்றும் நினைவகப் பரிந்துரையைப் பார்க்கவும். மொழிபெயர்ப்பு பின்னர் ஆஃப்லைனில் வேலை செய்யும்.",
    "intro4Title": "நீண்ட வேலைகளின் கட்டுப்பாட்டை வைத்திருங்கள்",
    "intro4Body": "வேலையை இடைநிறுத்தவும் அல்லது மீண்டும் தொடங்கவும் மற்றும் சேமிக்கப்பட்ட முடிவை மதிப்பாய்வு செய்யவும். பின்னணி வரம்புகள் உங்கள் சாதனம் மற்றும் கணினியைப் பொறுத்தது.",
